ess","interest_ids":[5,11],"is_free":true,"reuse_event_id":null},{"title":"Grievous Angels Band","starts_at":"2026-11-21T16:00:00-05:00","ends_at":"2026-11-21T19:00:00-05:00","venue":"Triple C Brewing Company","address":"2900 Griffith St, Charlotte, NC 28203","link":"https://www.triplecbrewing.com/live-music-events","details":"Live music from Grievous Angels.","source_handle":"triplecbrewing.com","image_url":"https://images.squarespace-cdn.com/content/v1/552bc631e4b0a253ae3ab53c/1747660352322-JLKI2UXKM0XPXWEZRBXE/Angels.jpg","submission_id":"7021376b-e4fb-42db-9937-b1e0e4fa7366","publish_address":"2900 Griffith St, Charlotte, NC 28203","lat":35.201084446944,"lng":-80.869092110523,"source":"US Census Public_AR_Current onelineaddress: 2900 GRIFFITH ST, CHARLOTTE, NC, 28203","precision":"street_address","interest_ids":[2],"is_free":false,"reuse_event_id":null},{"title":"Board Game Speed Dating at Heist Brewery (20s & 30s)","starts_at":"2026-11-23T19:00:00-05:00","ends_at":"2026-11-23T21:00:00-05:00","venue":"Heist Brewery — NoDa","address":"2909 N Davidson St STE 200, Charlotte, NC 28205","link":"https://heistbrewery.com/event/noda-board-game-speed-dating-heist-brewery-charlotte-20s-30s-2/","details":"Board-game speed dating at Heist Brewery. The organizer specifies men and women ages 25–39.","source_handle":"heistbrewery.com","image_url":"https://images.squarespace-cdn.com/content/v1/63067cdbea66711d3b62b6ce/0d64069f-0b8f-4040-9724-12b84aa009fc/BGSD.png","submission_id":"e9f3c2ed-5f0f-47f0-93fa-c67cd621096d","publish_address":"2909 N Davidson St STE 200, Charlotte, NC 28205","lat":35.245140179428,"lng":-80.809082558747,"source":"US Census Public_AR_Current onelineaddress: 2909 N DAVIDSON ST, CHARLOTTE, NC, 28205","precision":"street_address","interest_ids":[9],"is_free":false,"reuse_event_id":null}]'::jsonb) as b(
 submission_id uuid,title text,starts_at timestamptz,ends_at timestamptz,venue text,address text,
 link text,details text,source_handle text,image_url text,publish_address text,lat double precision,lng double precision,
 interest_ids smallint[],is_free boolean,reuse_event_id uuid
);
do $guard$
begin
 if (select count(*) from yard_requested)<>17 then raise exception 'Expected exactly 17 events'; end if;
 if (select count(distinct submission_id) from yard_requested)<>17 then raise exception 'Duplicate submission ids'; end if;
 if exists(select 1 from yard_requested where lat not between 35.0 and 35.5 or lng not between -81.1 and -80.5 or lat is null or lng is null) then raise exception 'Invalid Charlotte geocode'; end if;
 if (select count(*) from public.event_submissions s join yard_requested b on b.submission_id=s.id
  where s.origin='agent' and s.city_id=1 and s.status in ('pending','approved')
  and (s.status='pending' or s.event_id is not null)
  and s.title=b.title and s.starts_at=b.starts_at
  and s.ends_at is not distinct from b.ends_at and s.venue is not distinct from b.venue
  and s.address is not distinct from b.address and s.link is not distinct from b.link
  and s.details is not distinct from b.details and s.image_url=b.image_url
  and s.source_handle=b.source_handle)<>17 then raise exception 'Reviewed submissions changed or are missing'; end if;
end $guard$;
create temporary table yard_publish on commit drop as
select b.*,coalesce(s.event_id,b.reuse_event_id,gen_random_uuid()) as target_id,
 (s.event_id is not null or b.reuse_event_id is not null) as reuse_existing
from yard_requested b join public.event_submissions s on s.id=b.submission_id
for update of s;
do $guard$
begin
 if exists(select 1 from yard_publish b where b.reuse_event_id is not null and not exists(
  select 1 from public.events e where e.id=b.reuse_event_id and e.city_id=1
  and e.title in ('Festival Día de Muertos - Day of the Dead Festival','Festival Día de Muertos')
  and e.starts_at in ('2026-11-01T16:00:00Z'::timestamptz,'2026-11-01T17:00:00Z'::timestamptz)
 )) then raise exception 'Existing festival changed; recheck before merging'; end if;
 if exists(select 1 from yard_publish b join public.events e on e.city_id=1 and e.id<>b.target_id
  and lower(e.title)=lower(b.title) and abs(extract(epoch from e.starts_at-b.starts_at))<=3600
  and e.status<>'hidden') then raise exception 'New matching event found; recheck duplicates'; end if;
end $guard$;
insert into public.events(id,source,external_id,city_id,title,starts_at,ends_at,venue_name,venue_address,ticket_url,image_url,description,location,is_free,attribution,status)
select target_id,'curated','agent:'||submission_id::text,1,title,starts_at,ends_at,venue,publish_address,link,image_url,details,
 extensions.st_setsrid(extensions.st_makepoint(lng,lat),4326)::extensions.geography,is_free,
 'Source: '||source_handle,'active'
from yard_publish
on conflict(id) do update set
 source=excluded.source,external_id=excluded.external_id,title=excluded.title,
 starts_at=excluded.starts_at,ends_at=excluded.ends_at,venue_name=excluded.venue_name,
 venue_address=excluded.venue_address,ticket_url=excluded.ticket_url,image_url=excluded.image_url,
 description=excluded.description,location=excluded.location,is_free=excluded.is_free,
 attribution=excluded.attribution,status='active',updated_at=now();
insert into public.event_interests(event_id,interest_id)
select b.target_id,i.id from yard_publish b cross join lateral unnest(b.interest_ids) i(id)
on conflict do nothing;
update public.event_submissions s
set status='approved',event_id=b.target_id,reviewed_at=coalesce(s.reviewed_at,now()),
 admin_note='Approved by owner request; Astra-reviewed content and images. Published with verified venue location.'
from yard_publish b where s.id=b.submission_id;
do $guard$
begin
 if (select count(*) from yard_publish b join public.event_submissions s on s.id=b.submission_id
 join public.events e on e.id=s.event_id where s.status='approved' and e.status='active'
 and e.image_url=b.image_url and e.starts_at=b.starts_at)<>17 then raise exception 'Publication verification failed'; end if;
end $guard$;
select s.id as submission_id,s.event_id,s.status,e.title,e.starts_at,
 e.image_url is not null as has_image,b.reuse_existing
from yard_publish b join public.event_submissions s on s.id=b.submission_id join public.events e on e.id=s.event_id order by e.starts_at;
commit;
